//! Integration tests for [`pkix_identity::verify_dns_name_with_cn_fallback`],
//! the RFC 7672 §3.2.3 matching rule used by SMTP DANE.
//!
//! Oracle: DER fixtures generated by `tests/fixtures/gen.py` using
//! pyca/cryptography. See `tests/fixtures/README.md`.
//!
//! The rule has two halves and the second is the one worth testing hardest:
//! the CN is consulted *only* when no DNS-ID is present. An implementation
//! that consulted the CN whenever DNS-ID matching failed would pass every
//! positive test here and still be wrong in the way that matters, because it
//! would let a certificate's CN override its own SAN.

use der::Decode as _;
use pkix_identity::{verify_dns_name, verify_dns_name_with_cn_fallback, IdentityError, ServerName};
use x509_cert::Certificate;

fn load(name: &str) -> Certificate {
    let path = format!("tests/fixtures/{name}");
    let der = std::fs::read(&path).unwrap_or_else(|e| panic!("fixture not found: {path}: {e}"));
    Certificate::from_der(&der).unwrap_or_else(|e| panic!("invalid DER in {path}: {e}"))
}

fn dns(name: &str) -> ServerName<'_> {
    ServerName::dns_name(name).expect("test name is a valid DNS name")
}

// ---------------------------------------------------------------------------
// The CN is consulted when no DNS-ID is present
// ---------------------------------------------------------------------------

#[test]
fn cn_hostname_matches_when_there_is_no_san() {
    let cert = load("cn-hostname.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("mx.example.com")),
        Ok(())
    );
}

#[test]
fn cn_hostname_mismatch_is_reported() {
    let cert = load("cn-hostname.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("other.example.com")),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn cn_matching_is_case_insensitive() {
    let cert = load("cn-hostname.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("MX.Example.COM")),
        Ok(())
    );
}

/// A SAN that exists but carries no `dNSName` still triggers the CN-ID rule.
///
/// RFC 7672 §3.2.3 turns on whether a DNS-ID is *present*, not on whether a
/// SAN extension is present. An implementation keying off the extension
/// instead would skip the CN here and reject a working configuration.
#[test]
fn a_san_without_any_dns_id_falls_back_to_the_cn() {
    let cert = load("san-ip-plus-cn.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("mx.example.com")),
        Ok(())
    );
}

// ---------------------------------------------------------------------------
// The CN is NOT consulted when a DNS-ID is present
// ---------------------------------------------------------------------------

/// The central negative: a present DNS-ID excludes the CN entirely.
///
/// `san-dns-plus-cn.der` has `DNS:www.example.com` and `CN=mx.example.com`.
/// Asking for `mx.example.com` must fail. If this passes, the CN can override
/// the SAN, which is the failure RFC 6125 §6.4.4 deprecated CN fallback over
/// and which RFC 7672 §3.2.3 is careful to exclude.
#[test]
fn a_present_dns_id_means_the_cn_is_ignored() {
    let cert = load("san-dns-plus-cn.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("mx.example.com")),
        Err(IdentityError::NoMatchingSan),
        "the CN must not be consulted when the certificate presents a DNS-ID"
    );
}

#[test]
fn a_present_dns_id_still_matches_on_its_own_terms() {
    let cert = load("san-dns-plus-cn.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("www.example.com")),
        Ok(())
    );
}

// ---------------------------------------------------------------------------
// Wildcards, which RFC 7672 §3.2.3 permits in the CN-ID
// ---------------------------------------------------------------------------

#[test]
fn a_wildcard_cn_matches_exactly_one_label() {
    let cert = load("cn-wildcard.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("mx.example.com")),
        Ok(())
    );
}

/// RFC 7672 §3.2.3: wildcards match one label by default. Matching more is a
/// MAY subject to local policy, and this crate does not take it.
#[test]
fn a_wildcard_cn_does_not_match_two_labels() {
    let cert = load("cn-wildcard.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("a.mx.example.com")),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn a_wildcard_cn_does_not_match_the_bare_parent() {
    let cert = load("cn-wildcard.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("example.com")),
        Err(IdentityError::NoMatchingSan)
    );
}

// ---------------------------------------------------------------------------
// No presented identity at all
// ---------------------------------------------------------------------------

/// Distinguished from a CN that merely fails to match.
///
/// A caller logging why delivery was refused wants "this server presented no
/// name" separated from "it presented the wrong name"; the first suggests a
/// misissued certificate, the second a misdirected connection.
#[test]
fn no_san_and_no_cn_is_missing_san() {
    let cert = load("no-san-no-cn.der");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &dns("mx.example.com")),
        Err(IdentityError::MissingSan)
    );
}

// ---------------------------------------------------------------------------
// IP literals delegate unchanged
// ---------------------------------------------------------------------------

/// RFC 7672's reference identifiers are domain names, so the CN-ID rule has
/// nothing to say about IP targets and this function must behave exactly as
/// [`verify_dns_name`] for them.
#[test]
fn ip_targets_behave_as_in_the_web_pki_path() {
    let cert = load("san-ipv4.der");
    let ip = ServerName::ip_address("192.0.2.5").expect("valid IPv4 literal");
    assert_eq!(verify_dns_name_with_cn_fallback(&cert, &ip), Ok(()));
    assert_eq!(verify_dns_name(&cert, &ip), Ok(()));
}

/// An IP target is never satisfied by a CN, even with no DNS-ID present.
#[test]
fn an_ip_target_is_not_matched_against_the_cn() {
    let cert = load("san-ip-plus-cn.der");
    let wrong = ServerName::ip_address("198.51.100.1").expect("valid IPv4 literal");
    assert_eq!(
        verify_dns_name_with_cn_fallback(&cert, &wrong),
        Err(IdentityError::NoMatchingSan)
    );
}

// ---------------------------------------------------------------------------
// The Web PKI path is unchanged
// ---------------------------------------------------------------------------

/// Adding the SMTP rule must not loosen the default one.
///
/// Without this, a refactor that routed `verify_dns_name` through the new
/// implementation would silently give the Web PKI CN fallback back.
#[test]
fn the_web_pki_function_still_refuses_a_cn_only_certificate() {
    for fixture in ["cn-hostname.der", "cn-wildcard.der", "cn-only.der"] {
        let cert = load(fixture);
        assert_eq!(
            verify_dns_name(&cert, &dns("mx.example.com")),
            Err(IdentityError::MissingSan),
            "{fixture}: verify_dns_name must not consult the CN"
        );
    }
}

/// And the Web PKI path still ignores a CN when a SAN is present.
#[test]
fn the_web_pki_function_ignores_the_cn_when_a_san_exists() {
    let cert = load("san-dns-plus-cn.der");
    assert_eq!(
        verify_dns_name(&cert, &dns("mx.example.com")),
        Err(IdentityError::NoMatchingSan)
    );
}
